import 'package:flutter/material.dart';
import 'package:provider/provider.dart';
void main(){runApp(ChangeNotifierProvider(create:(_)=>Cart(),child:const SareeApp()));}
class Cart extends ChangeNotifier{int count=0;int total=0;void add(int price){count++;total+=price;notifyListeners();}void clear(){count=0;total=0;notifyListeners();}}
class SareeApp extends StatelessWidget{const SareeApp({super.key});@override Widget build(BuildContext context)=>MaterialApp(debugShowCheckedModeBanner:false,title:'سريع',theme:ThemeData(useMaterial3:true,colorScheme:ColorScheme.fromSeed(seedColor:const Color(0xFFFF6B35))),home:const Directionality(textDirection:TextDirection.rtl,child:Home()));}
class Home extends StatelessWidget{const Home({super.key});@override Widget build(BuildContext context)=>Scaffold(appBar:AppBar(title:const Text('سريع - توصيل الطعام في رداع'),actions:[Consumer<Cart>(builder:(_,c,__)=>Badge(label:Text(c.count.toString()),child:IconButton(icon:const Icon(Icons.shopping_cart),onPressed:()=>Navigator.push(context,MaterialPageRoute(builder:(_)=>const CartPage()))))) ]),body:ListView(padding:const EdgeInsets.all(16),children:[const ListTile(leading:Icon(Icons.location_on),title:Text('موقع التوصيل'),subtitle:Text('رداع، اليمن')),const Text('الأقسام',style:TextStyle(fontSize:20,fontWeight:FontWeight.bold)),Wrap(spacing:8,children:['وجبات سريعة','مشويات','شعبية','حلويات'].map((x)=>Chip(label:Text(x))).toList()),const SizedBox(height:16),const Text('المطاعم المتاحة',style:TextStyle(fontSize:20,fontWeight:FontWeight.bold)),...['مطعم الذوق','مطعم رداع الشعبي'].map((n)=>Card(child:ListTile(leading:const CircleAvatar(child:Icon(Icons.restaurant)),title:Text(n),subtitle:const Text('⭐ 4.7 • 30 دقيقة • مفتوح'),onTap:()=>Navigator.push(context,MaterialPageRoute(builder:(_)=>Restaurant(name:n))))))]));}
class Restaurant extends StatelessWidget{final String name;const Restaurant({super.key,required this.name});@override Widget build(BuildContext context)=>Scaffold(appBar:AppBar(title:Text(name)),body:ListView(padding:const EdgeInsets.all(16),children:[const Text('المنيو',style:TextStyle(fontSize:22,fontWeight:FontWeight.bold)),food(context,'وجبة دجاج',3500),food(context,'برجر لحم',3000),food(context,'وجبة مشويات',5000)]));Widget food(BuildContext context,String n,int p)=>Card(child:ListTile(title:Text(n),subtitle:Text(p.toString()+' ريال يمني'),trailing:IconButton(icon:const Icon(Icons.add_circle),onPressed:()=>context.read<Cart>().add(p))));}
class CartPage extends StatelessWidget{const CartPage({super.key});@override Widget build(BuildContext context)=>Scaffold(appBar:AppBar(title:const Text('سلة الطلب')),body:Consumer<Cart>(builder:(_,c,__)=>(c.count==0)?const Center(child:Text('السلة فارغة')):Padding(padding:const EdgeInsets.all(20),child:Column(children:[Text('عدد الأصناف: '+c.count.toString()),Text('الإجمالي: '+(c.total+1000).toString()+' ريال يمني'),const SizedBox(height:20),ElevatedButton(onPressed:(){c.clear();Navigator.pushReplacement(context,MaterialPageRoute(builder:(_)=>const Tracking()));},child:const Text('تأكيد الطلب - الدفع عند الاستلام'))]))));}
class Tracking extends StatefulWidget{const Tracking({super.key});@override State<Tracking> createState()=>_TrackingState();}class _TrackingState extends State<Tracking>{int step=0;bool cancelled=false;final s=['تم إرسال الطلب','تم استلام الطلب بواسطة المطعم','جاري تحضير الطلب','في طريق التوصيل','تم التوصيل'];@override Widget build(BuildContext context)=>Scaffold(appBar:AppBar(title:const Text('تتبع الطلب')),body:Padding(padding:const EdgeInsets.all(20),child:Column(children:[const Icon(Icons.delivery_dining,size:90),if(cancelled)const Text('تم إلغاء الطلب')else ...[...List.generate(s.length,(i)=>ListTile(leading:Icon(i<=step?Icons.check_circle:Icons.radio_button_unchecked),title:Text(s[i]))),if(step<4)ElevatedButton(onPressed:()=>setState(()=>step++),child:Text(step==3?'تأكيد استلام الطلب':'تحديث حالة الطلب')),if(step<2)OutlinedButton(onPressed:()=>setState(()=>cancelled=true),child:const Text('إلغاء الطلب'))]])));}